    const craters = [];
    const nc = (b.cover && b.cover.rocks ? 1 : 0) + ((amp.craters || 0) > 0 ? Math.round(6 + (amp.craters || 0) * 20) : 0) + ((b.cover && b.cover.vents) ? Math.round(8 * b.cover.vents) : 0);
